#include <stdio.h>

int main() {
    int tide = 3;
    int age = 19;

    printf("tide == 3  -> %d\n", tide == 3);
    printf("tide != 3  -> %d\n", tide != 3);
    printf("age >= 18  -> %d\n", age >= 18);
    printf("age < 13   -> %d\n", age < 13);

    int hasTicket = 1;
    int busFull = 0;

    printf("can board  -> %d\n", hasTicket && !busFull);
    printf("weekend or holiday -> %d\n", 0 || 1);
    printf("!hasTicket -> %d\n", !hasTicket);
    return 0;
}

